<script setup lang="ts">
import { AlertTriangle, Box, Building2, Check, Clock3, ContactRound, RefreshCw, RotateCcw, Search, ShieldAlert, Trash2, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const { token } = useWorkspaceSession();
const entries = ref<any[]>([]);
const selected = ref<any>(null);
const preview = ref<any>(null);
const type = ref('');
const search = ref('');
const busy = ref(false);
const error = ref('');
const notice = ref('');
const confirmation = ref('');
const adminPassword = ref('');
let timer: ReturnType<typeof setTimeout>|undefined;
const headers = computed(()=>({Authorization:`Bearer ${token.value}`}));
const types = [{id:'',label:'Все данные',icon:Trash2},{id:'USER',label:'Учётные записи',icon:ContactRound},{id:'CUSTOMER',label:'Клиенты',icon:Users},{id:'ORGANIZATION',label:'Организации',icon:Building2},{id:'PRODUCT',label:'Товары',icon:Box},{id:'CATEGORY',label:'Категории',icon:Box}];
const typeLabels:Record<string,string>={USER:'Учётная запись',CUSTOMER:'Клиент',ORGANIZATION:'Организация B2B',PRODUCT:'Товар',CATEGORY:'Категория'};
async function load(){busy.value=true;error.value='';try{const result=await $fetch<any>('/data-lifecycle/trash',{baseURL:config.public.apiBase,headers:headers.value,query:{type:type.value||undefined,search:search.value||undefined}});entries.value=result.items}catch(exception:any){error.value=messageOf(exception)}finally{busy.value=false}}
async function openEntry(entry:any){selected.value=entry;confirmation.value='';adminPassword.value='';preview.value=null;error.value='';try{preview.value=await $fetch(`/data-lifecycle/${entry.entityType}/${entry.entityId}/preview`,{baseURL:config.public.apiBase,headers:headers.value})}catch(exception:any){error.value=messageOf(exception)}}
async function restore(){if(!selected.value)return;await act(async()=>{await $fetch(`/data-lifecycle/trash/${selected.value.id}/restore`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value});selected.value=null;await load();showNotice('Данные восстановлены')})}
async function purge(){if(!selected.value)return;await act(async()=>{await $fetch(`/data-lifecycle/trash/${selected.value.id}`,{baseURL:config.public.apiBase,method:'DELETE',headers:headers.value,body:{confirmation:confirmation.value,currentAdminPassword:adminPassword.value}});selected.value=null;await load();showNotice('Данные окончательно удалены')})}
async function act(callback:()=>Promise<void>){busy.value=true;error.value='';try{await callback()}catch(exception:any){error.value=messageOf(exception)}finally{busy.value=false}}
function messageOf(exception:any){return exception?.data?.message||exception?.message||'Не удалось выполнить действие'}
function showNotice(value:string){notice.value=value;setTimeout(()=>notice.value='',2600)}
function daysLeft(value:string){return Math.max(0,Math.ceil((new Date(value).getTime()-Date.now())/86400000))}
watch(type,load);watch(search,()=>{if(timer)clearTimeout(timer);timer=setTimeout(load,350)});onMounted(load);
</script>

<template><section class="trash-workspace"><aside class="trash-types"><header><p>ФИЛЬТР</p><h2>Тип данных</h2></header><button v-for="item in types" :key="item.id" :class="{active:type===item.id}" @click="type=item.id"><component :is="item.icon" :size="16"/><span>{{item.label}}</span><b>{{item.id?entries.filter(row=>row.entityType===item.id).length:entries.length}}</b></button><div class="retention"><Clock3 :size="18"/><span><strong>Хранение 30 дней</strong><small>До окончательного удаления объект можно восстановить вместе с его состоянием.</small></span></div></aside><main class="trash-card"><header><div><p>БЕЗОПАСНОЕ УДАЛЕНИЕ</p><h2>Объекты в корзине</h2><span>{{entries.length}} объектов ожидают решения</span></div><div class="actions"><label><Search :size="16"/><input v-model.trim="search" placeholder="Поиск по названию"/></label><button title="Обновить" @click="load"><RefreshCw :size="16" :class="{spin:busy}"/></button></div></header><div class="trash-table"><div class="trash-row head"><span>Объект</span><span>Тип</span><span>Удалил</span><span>Осталось</span><span></span></div><button v-for="entry in entries" :key="entry.id" class="trash-row" @click="openEntry(entry)"><span><i><component :is="types.find(item=>item.id===entry.entityType)?.icon||Trash2" :size="16"/></i><span><strong>{{entry.displayName}}</strong><small>{{entry.reason||'Причина не указана'}}</small></span></span><span>{{typeLabels[entry.entityType]||entry.entityType}}</span><span>{{[entry.actor?.firstName,entry.actor?.lastName].filter(Boolean).join(' ')||entry.actor?.email||'Система'}}</span><span><b>{{daysLeft(entry.purgeAfter)}}</b> дн.</span><RotateCcw :size="16"/></button><div v-if="!entries.length&&!busy" class="empty"><Trash2 :size="30"/><strong>Корзина пуста</strong><span>Удалённые объекты появятся здесь и будут доступны для восстановления.</span></div></div></main><Teleport to="body"><div v-if="selected" class="trash-backdrop" @mousedown.self="selected=null"><aside class="trash-drawer"><header><div><p>{{typeLabels[selected.entityType]}}</p><h2>{{selected.displayName}}</h2><span>В корзине с {{new Date(selected.trashedAt).toLocaleString('ru-RU')}}</span></div><button @click="selected=null"><X :size="19"/></button></header><div class="drawer-body"><section class="restore-block"><RotateCcw :size="22"/><div><h3>Объект можно восстановить</h3><p>Будет возвращено состояние, которое было до перемещения в корзину.</p></div><button @click="restore">Восстановить</button></section><section><div class="section-title"><div><h3>Связи и последствия</h3><p>Финансовая и операционная история защищена от каскадного удаления.</p></div><ShieldAlert :size="19"/></div><div v-if="preview" class="dependencies"><article v-for="dependency in preview.dependencies" :key="dependency.key" :class="{blocking:dependency.blocking&&dependency.count}"><span>{{dependency.label}}</span><b>{{dependency.count}}</b><small>{{dependency.blocking&&dependency.count?'блокирует удаление':'не блокирует'}}</small></article></div></section><section class="danger-zone"><div class="section-title"><div><h3>Окончательное удаление</h3><p>Действие нельзя отменить. Снимок персональных данных также будет очищен.</p></div><AlertTriangle :size="19"/></div><div v-if="preview&&!preview.canPurge" class="blocked"><ShieldAlert :size="17"/><span><strong>Удаление сейчас запрещено</strong><small>Сначала обработайте перечисленные выше связанные данные.</small></span></div><template v-else><label><span>Введите точно: <b>{{selected.displayName}}</b></span><input v-model="confirmation"/></label><label><span>Пароль администратора</span><input v-model="adminPassword" type="password" autocomplete="current-password"/></label><button class="purge" :disabled="confirmation!==selected.displayName||!adminPassword||busy" @click="purge"><Trash2 :size="16"/>Удалить без возможности восстановления</button></template></section></div></aside></div></Teleport><p v-if="error" class="trash-error">{{error}}</p><p v-if="notice" class="trash-notice"><Check :size="15"/>{{notice}}</p></section></template>

<style scoped>
.trash-workspace{display:grid;grid-template-columns:230px 1fr;gap:18px;color:var(--sb-text)}.trash-types,.trash-card{background:#fff;border:1px solid var(--sb-line)}.trash-types{padding:20px 12px;align-self:start}.trash-types header{padding:3px 8px 14px}.trash-types p,.trash-card>header p,.trash-drawer>header p{margin:0 0 7px;color:var(--sb-coral);font-size:8px;font-weight:700;letter-spacing:.15em}.trash-types h2{margin:0;font-size:15px}.trash-types>button{width:100%;height:42px;border:0;background:transparent;display:flex;align-items:center;gap:9px;padding:0 9px;color:var(--sb-muted);font-size:9px;text-align:left}.trash-types>button.active{background:var(--sb-ink-soft);color:#fff}.trash-types>button.active svg{color:var(--sb-coral)}.trash-types>button b{margin-left:auto;font-size:9px}.retention{margin:18px 7px 2px;padding:14px 0 0;border-top:1px solid var(--sb-line);display:flex;gap:9px;color:var(--sb-muted)}.retention span{display:grid;gap:4px}.retention strong{font-size:9px;color:var(--sb-text)}.retention small{font-size:8px;line-height:1.5}.trash-card>header{min-height:102px;padding:22px 25px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--sb-line);box-sizing:border-box}.trash-card h2{font-size:19px;margin:0 0 5px}.trash-card header span{font-size:8px;color:var(--sb-muted)}.actions{display:flex;gap:7px}.actions label{width:270px;height:39px;border:1px solid var(--sb-line);display:flex;align-items:center;gap:8px;padding:0 10px;color:var(--sb-muted)}.actions input{border:0;outline:0;width:100%;font-size:9px}.actions>button{width:39px;height:39px;border:1px solid var(--sb-line);background:#fff}.trash-row{width:100%;min-height:62px;padding:9px 24px;box-sizing:border-box;display:grid;grid-template-columns:1.7fr .8fr 1fr .6fr 20px;gap:14px;align-items:center;border:0;border-bottom:1px solid var(--sb-line);background:#fff;text-align:left;font-size:9px;color:var(--sb-text)}button.trash-row{cursor:pointer}.trash-row:not(.head):hover{background:#fafafa}.trash-row.head{min-height:41px;color:var(--sb-muted);font-size:8px;text-transform:uppercase}.trash-row>span:first-child{display:flex;align-items:center;gap:10px}.trash-row>span:first-child>i{width:32px;height:32px;background:#f0f1f3;display:grid;place-items:center;color:var(--sb-muted)}.trash-row>span:first-child>span{display:grid;gap:4px}.trash-row small{font-size:8px;color:var(--sb-muted)}.trash-row>span:nth-child(4) b{font-size:15px;font-weight:500}.trash-row>svg{color:var(--sb-muted)}.empty{height:260px;display:grid;place-items:center;align-content:center;gap:8px;color:var(--sb-muted)}.empty strong{font-size:11px;color:var(--sb-text)}.empty span{font-size:8px}.trash-backdrop{position:fixed;z-index:1250;inset:0;background:#1011137a;display:flex;justify-content:flex-end;font-family:var(--sb-font);color:var(--sb-text)}.trash-drawer{width:min(570px,100vw);height:100%;background:var(--sb-bg);box-shadow:-18px 0 55px #0003;overflow:auto}.trash-drawer>header{height:96px;background:#fff;border-bottom:1px solid var(--sb-line);padding:0 27px;display:flex;align-items:center;justify-content:space-between}.trash-drawer h2{font-size:21px;margin:0 0 5px}.trash-drawer header span{font-size:8px;color:var(--sb-muted)}.trash-drawer header button{width:38px;height:38px;border:1px solid var(--sb-line);background:#fff}.drawer-body{padding:20px;display:grid;gap:15px}.drawer-body>section{background:#fff;border:1px solid var(--sb-line);padding:20px;display:grid;gap:17px}.restore-block{grid-template-columns:auto 1fr auto;align-items:center}.restore-block>svg{color:var(--sb-success)}.restore-block h3,.section-title h3{margin:0 0 5px;font-size:14px}.restore-block p,.section-title p{margin:0;color:var(--sb-muted);font-size:8px;line-height:1.5}.restore-block button{height:38px;border:1px solid var(--sb-ink);background:var(--sb-ink);color:#fff;padding:0 13px;font-size:9px}.section-title{display:flex;justify-content:space-between;gap:15px}.section-title>svg{color:var(--sb-coral)}.dependencies{display:grid}.dependencies article{min-height:42px;border-top:1px solid var(--sb-line);display:grid;grid-template-columns:1fr 35px 85px;gap:10px;align-items:center;font-size:9px}.dependencies article:first-child{border-top:0}.dependencies b{font-size:12px}.dependencies small{font-size:8px;color:var(--sb-success)}.dependencies .blocking small{color:var(--sb-danger)}.danger-zone{border-color:#f0b5ac!important}.danger-zone label{display:grid;gap:7px}.danger-zone label span{font-size:8px;color:var(--sb-muted)}.danger-zone input{height:41px;border:1px solid var(--sb-line);padding:0 10px;font-size:10px}.blocked{padding:12px;background:var(--sb-coral-soft);color:var(--sb-danger);display:flex;gap:9px}.blocked span{display:grid;gap:4px}.blocked strong{font-size:9px}.blocked small{font-size:8px}.purge{height:42px;border:0;background:var(--sb-danger);color:#fff;display:flex;align-items:center;justify-content:center;gap:8px;font-size:9px}.purge:disabled{opacity:.45}.trash-error,.trash-notice{position:fixed;z-index:1400;right:25px;bottom:22px;padding:12px 14px;margin:0;box-shadow:var(--sb-shadow);font-size:9px}.trash-error{background:var(--sb-coral-soft);color:var(--sb-danger)}.trash-notice{background:var(--sb-success);color:#fff;display:flex;gap:7px;align-items:center}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:950px){.trash-workspace{grid-template-columns:1fr}.trash-types{display:flex;overflow:auto}.trash-types header,.retention{display:none}.trash-types>button{min-width:max-content}}@media(max-width:650px){.trash-card>header{align-items:flex-start;flex-direction:column;gap:15px}.actions,.actions label{width:100%}.trash-row{grid-template-columns:1fr .7fr 20px}.trash-row>span:nth-child(3),.trash-row>span:nth-child(4){display:none}.restore-block{grid-template-columns:auto 1fr}.restore-block button{grid-column:1/-1}.drawer-body{padding:12px}}
</style>
